class TweetCounts { private final Map<String,TreeMap<Integer,Integer>> records=new HashMap<>();public void recordTweet(String tweetName,int time){records.computeIfAbsent(tweetName,key->new TreeMap<>()).merge(time,1,Integer::sum);}public List<Integer> getTweetCountsPerFrequency(String freq,String tweetName,int startTime,int endTime){int width=freq.equals("minute")?60:freq.equals("hour")?3600:86400;List<Integer> answer=new ArrayList<>(Collections.nCopies((endTime-startTime)/width+1,0));TreeMap<Integer,Integer> times=records.getOrDefault(tweetName,new TreeMap<>());for(Map.Entry<Integer,Integer> entry:times.subMap(startTime,true,endTime,true).entrySet()){int index=(entry.getKey()-startTime)/width;answer.set(index,answer.get(index)+entry.getValue());}return answer;} }
